'use client';

import { useState, useCallback, useEffect, useRef } from 'react';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { useCanvasStore } from '@/lib/store/canvas-store';
import { ANNOTATION_COLORS } from '@/lib/utils/constants';
import type { AnnotationNodeData } from '@/lib/types/canvas';
import { cn } from '@/lib/utils';

interface AnnotationPropertiesProps {
  nodeId: string;
  data: AnnotationNodeData;
}

export function AnnotationProperties({
  nodeId,
  data,
}: AnnotationPropertiesProps) {
  const updateAnnotationNodeData = useCanvasStore(
    (s) => s.updateAnnotationNodeData
  );
  const [content, setContent] = useState(data.content);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setContent(data.content);
  }, [nodeId, data.content]);

  const handleContentBlur = useCallback(() => {
    if (content !== data.content) {
      updateAnnotationNodeData(nodeId, { content });
    }
  }, [content, data.content, nodeId, updateAnnotationNodeData]);

  const handleColorChange = useCallback(
    (color: string) => {
      updateAnnotationNodeData(nodeId, { color });
    },
    [nodeId, updateAnnotationNodeData]
  );

  const handleImageUpload = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        updateAnnotationNodeData(nodeId, { image: reader.result as string });
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    },
    [nodeId, updateAnnotationNodeData]
  );

  const handleRemoveImage = useCallback(() => {
    updateAnnotationNodeData(nodeId, { image: null });
  }, [nodeId, updateAnnotationNodeData]);

  return (
    <div className="p-4 space-y-4">
      <h3 className="font-semibold text-sm">Annotation Properties</h3>

      <div className="space-y-2">
        <Label className="text-xs">Content</Label>
        <textarea
          className="w-full min-h-[100px] rounded-md border bg-transparent px-3 py-2 text-sm resize-y"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          onBlur={handleContentBlur}
          placeholder="Type text here... Use $..$ for inline math, $$...$$ for display math"
        />
        <p className="text-[10px] text-muted-foreground">
          Supports LaTeX: $E=mc^2$ or $$\sum_&#123;i=0&#125;^n x_i$$
        </p>
      </div>

      <div className="space-y-2">
        <Label className="text-xs">Color</Label>
        <div className="flex gap-1.5 flex-wrap">
          {ANNOTATION_COLORS.map((c) => (
            <button
              key={c.name}
              className={cn(
                'h-6 w-6 rounded border-2 transition-all hover:scale-110',
                data.color === c.value
                  ? 'border-foreground'
                  : 'border-transparent'
              )}
              style={{ backgroundColor: c.value }}
              onClick={() => handleColorChange(c.value)}
              title={c.name}
            />
          ))}
        </div>
      </div>

      <Separator />

      <div className="space-y-2">
        <Label className="text-xs">Image</Label>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          hidden
          onChange={handleImageUpload}
        />
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => fileInputRef.current?.click()}
          >
            {data.image ? 'Replace' : 'Add'} Image
          </Button>
          {data.image && (
            <Button variant="outline" size="sm" onClick={handleRemoveImage}>
              Remove
            </Button>
          )}
        </div>
        {data.image && (
          <img
            src={data.image}
            alt="annotation"
            className="max-w-full max-h-32 rounded border"
          />
        )}
      </div>
    </div>
  );
}

'use client';

import { useCallback } from 'react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useProjectStore } from '@/lib/store/project-store';
import { useCanvasStore } from '@/lib/store/canvas-store';
import { deserializeSystemToCanvas } from '@/lib/persistence/serializer';
import type { ChartBlockNodeData } from '@/lib/types/canvas';
import type { Port } from '@/lib/types/chart';
import type { DataType } from '@/lib/types/variable';
import { generateId } from '@/lib/utils/id-generator';
import { LayoutGrid, Plus, Trash2 } from 'lucide-react';

interface Props {
  nodeId: string;
  data: ChartBlockNodeData;
}

export function ChartBlockProperties({ nodeId, data }: Props) {
  const chart = useProjectStore((s) =>
    s.currentProject?.charts.find((c) => c.id === data.chartId)
  );

  const refreshCanvas = useCallback(() => {
    const project = useProjectStore.getState().currentProject;
    if (project) {
      const { nodes, edges } = deserializeSystemToCanvas(project);
      useCanvasStore.getState().setNodes(nodes);
      useCanvasStore.getState().setEdges(edges);
    }
  }, []);

  const handleRename = useCallback(
    (name: string) => {
      useProjectStore.getState().renameChart(data.chartId, name);
      refreshCanvas();
    },
    [data.chartId, refreshCanvas]
  );

  const handleDescriptionChange = useCallback(
    (description: string) => {
      const store = useProjectStore.getState();
      const current = store.currentProject;
      if (!current) return;
      store.setCurrentProject({
        ...current,
        charts: current.charts.map((c) =>
          c.id === data.chartId ? { ...c, description } : c
        ),
      });
    },
    [data.chartId]
  );

  const handleUpdatePorts = useCallback(
    (ports: Port[]) => {
      useProjectStore.getState().updateChartPorts(data.chartId, ports);
      refreshCanvas();
    },
    [data.chartId, refreshCanvas]
  );

  const handleAddPort = useCallback(() => {
    const newPort: Port = {
      id: generateId(),
      name: `port_${(chart?.ports.length ?? 0) + 1}`,
      direction: 'input',
      dataType: 'REAL' as DataType,
      defaultValue: '0',
    };
    handleUpdatePorts([...(chart?.ports ?? []), newPort]);
  }, [chart?.ports, handleUpdatePorts]);

  const handleRemovePort = useCallback(
    (portId: string) => {
      handleUpdatePorts((chart?.ports ?? []).filter((p) => p.id !== portId));
    },
    [chart?.ports, handleUpdatePorts]
  );

  const handlePortChange = useCallback(
    (portId: string, updates: Partial<Port>) => {
      handleUpdatePorts(
        (chart?.ports ?? []).map((p) =>
          p.id === portId ? { ...p, ...updates } : p
        )
      );
    },
    [chart?.ports, handleUpdatePorts]
  );

  if (!chart) return null;

  return (
    <div className="space-y-4 p-4">
      <div className="flex items-center gap-2 mb-3">
        <LayoutGrid className="h-4 w-4 text-primary" />
        <h3 className="font-semibold text-sm">Chart Block</h3>
      </div>

      <div className="space-y-2">
        <Label className="text-xs">Name</Label>
        <Input
          value={chart.name}
          onChange={(e) => handleRename(e.target.value)}
          className="h-8 text-sm"
        />
      </div>

      <div className="space-y-2">
        <Label className="text-xs">Description</Label>
        <textarea
          value={chart.description}
          onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => handleDescriptionChange(e.target.value)}
          className="flex min-h-[60px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          placeholder="Chart description..."
        />
      </div>

      {/* Port editor */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label className="text-xs">Ports</Label>
          <Button variant="ghost" size="sm" className="h-6 px-2" onClick={handleAddPort}>
            <Plus className="h-3 w-3 mr-1" />
            <span className="text-xs">Add</span>
          </Button>
        </div>

        {chart.ports.length === 0 ? (
          <p className="text-xs text-muted-foreground">
            No ports defined. Add ports to wire this chart to other blocks.
          </p>
        ) : (
          <div className="space-y-2">
            {chart.ports.map((port) => (
              <div
                key={port.id}
                className="flex items-center gap-1 rounded border p-1.5"
              >
                <Input
                  value={port.name}
                  onChange={(e) => handlePortChange(port.id, { name: e.target.value })}
                  className="h-6 text-xs flex-1 min-w-0"
                />
                <Select
                  value={port.direction}
                  onValueChange={(v) =>
                    handlePortChange(port.id, { direction: v as 'input' | 'output' })
                  }
                >
                  <SelectTrigger className="h-6 text-xs w-[70px]">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="input">In</SelectItem>
                    <SelectItem value="output">Out</SelectItem>
                  </SelectContent>
                </Select>
                <Select
                  value={port.dataType}
                  onValueChange={(v) =>
                    handlePortChange(port.id, { dataType: v as DataType })
                  }
                >
                  <SelectTrigger className="h-6 text-xs w-[70px]">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="BOOL">BOOL</SelectItem>
                    <SelectItem value="INT">INT</SelectItem>
                    <SelectItem value="REAL">REAL</SelectItem>
                  </SelectContent>
                </Select>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-6 w-6 flex-shrink-0"
                  onClick={() => handleRemovePort(port.id)}
                >
                  <Trash2 className="h-3 w-3" />
                </Button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useMemo, useState, useEffect } from 'react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Button } from '@/components/ui/button';
import { useUIStore } from '@/lib/store/ui-store';
import { useCanvasStore } from '@/lib/store/canvas-store';
import { useProjectStore } from '@/lib/store/project-store';
import { useNavigationStore } from '@/lib/store/navigation-store';
import { Code2, Copy, Download, AlertTriangle } from 'lucide-react';
import { generateProject } from '@/lib/codegen/project-generator';
import { downloadFile } from '@/lib/persistence/exporter';
import type { GeneratedFile } from '@/lib/types/codegen';

export function CodePreviewPanel() {
  const preferredLanguage = useUIStore((s) => s.codePreviewLanguage);
  const nodes = useCanvasStore((s) => s.nodes);
  const edges = useCanvasStore((s) => s.edges);
  const project = useProjectStore((s) => s.currentProject);
  const chartId = useNavigationStore((s) =>
    s.activeView.type === 'chart' ? s.activeView.chartId : null
  );
  const variables = useProjectStore((s) => {
    if (!chartId || !s.currentProject) return [];
    const chart = s.currentProject.charts.find((c) => c.id === chartId);
    return chart?.variables ?? [];
  });
  const chartName = useProjectStore((s) => {
    if (!chartId || !s.currentProject) return s.currentProject?.name ?? 'StateMachine';
    const chart = s.currentProject.charts.find((c) => c.id === chartId);
    return chart?.name ?? 'StateMachine';
  });

  const stateCount = nodes.filter((n) => n.type === 'stateNode').length;

  const generated = useMemo(() => {
    if (stateCount === 0) {
      return { files: [] as GeneratedFile[], messages: [] };
    }

    return generateProject({
      nodes,
      edges,
      variables,
      projectName: chartName,
      target: 'both',
    });
  }, [nodes, edges, variables, chartName, stateCount]);

  const warnings = generated.messages.filter((m) => m.level === 'warning');
  const errors = generated.messages.filter((m) => m.level === 'error');

  const [selectedFileIdx, setSelectedFileIdx] = useState(0);

  // When files change, select first file matching preferred language, or clamp index
  useEffect(() => {
    if (generated.files.length === 0) {
      setSelectedFileIdx(0);
      return;
    }
    const preferredIdx = generated.files.findIndex(
      (f) => f.language === preferredLanguage
    );
    if (preferredIdx >= 0) {
      setSelectedFileIdx(preferredIdx);
    } else if (selectedFileIdx >= generated.files.length) {
      setSelectedFileIdx(0);
    }
    // Only run when files change or preferred language changes
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [generated.files.length, preferredLanguage]);

  const selectedFile = generated.files[selectedFileIdx] ?? null;

  const handleCopy = () => {
    if (selectedFile) {
      navigator.clipboard.writeText(selectedFile.content);
    }
  };

  const handleDownload = () => {
    if (!selectedFile) return;
    const mime = selectedFile.language === 'c' ? 'text/x-c' : 'text/plain';
    downloadFile(selectedFile.content, selectedFile.filename, mime);
  };

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b px-2 py-1">
        <span className="text-xs font-medium text-muted-foreground flex items-center gap-1">
          <Code2 className="h-3 w-3" />
          Code Preview
          {(errors.length > 0 || warnings.length > 0) && (
            <span className="flex items-center gap-0.5 ml-1">
              {errors.length > 0 && (
                <span className="text-destructive text-[10px]">
                  {errors.length} err
                </span>
              )}
              {warnings.length > 0 && (
                <span className="text-yellow-500 text-[10px] flex items-center gap-0.5">
                  <AlertTriangle className="h-2.5 w-2.5" />
                  {warnings.length}
                </span>
              )}
            </span>
          )}
        </span>
        <div className="flex items-center gap-1">
          {stateCount > 0 && (
            <>
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6"
                onClick={handleCopy}
                title="Copy to clipboard"
              >
                <Copy className="h-3 w-3" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6"
                onClick={handleDownload}
                title="Download file"
              >
                <Download className="h-3 w-3" />
              </Button>
            </>
          )}
        </div>
      </div>

      {/* File tabs */}
      {generated.files.length > 0 && (
        <div className="flex border-b overflow-x-auto">
          {generated.files.map((file, idx) => (
            <button
              key={file.filename}
              className={`px-3 py-1 text-xs font-mono border-b-2 whitespace-nowrap transition-colors ${
                idx === selectedFileIdx
                  ? 'border-primary text-foreground'
                  : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
              onClick={() => setSelectedFileIdx(idx)}
            >
              {file.filename}
            </button>
          ))}
        </div>
      )}

      {/* File content */}
      <div className="flex-1 min-h-0">
        <ScrollArea className="h-full">
          <pre className="p-3 text-xs font-mono leading-relaxed whitespace-pre">
            {selectedFile ? (
              selectedFile.language === 'c' ? (
                <HighlightedC code={selectedFile.content} />
              ) : (
                <HighlightedSCL code={selectedFile.content} />
              )
            ) : (
              <span className="text-muted-foreground">
                {'/* Add states to see generated code */'}
              </span>
            )}
          </pre>
        </ScrollArea>
      </div>
    </div>
  );
}

function HighlightedC({ code }: { code: string }) {
  const lines = code.split('\n');
  return (
    <>
      {lines.map((line, i) => (
        <CLine key={i} line={line} />
      ))}
    </>
  );
}

function CLine({ line }: { line: string }) {
  // Comment lines
  if (line.trimStart().startsWith('/*') || line.trimStart().startsWith('//')) {
    return <span className="text-muted-foreground/60">{line}{'\n'}</span>;
  }

  // Preprocessor
  if (line.trimStart().startsWith('#')) {
    return <span className="text-purple-400">{line}{'\n'}</span>;
  }

  // Highlight keywords and types inline
  const parts = tokenizeCLine(line);
  return (
    <span>
      {parts.map((part, i) => (
        <span key={i} className={part.className}>{part.text}</span>
      ))}
      {'\n'}
    </span>
  );
}

function tokenizeCLine(line: string): { text: string; className: string }[] {
  const C_KEYWORDS = /\b(typedef|enum|struct|void|switch|case|break|default|if|else|return|const)\b/g;
  const C_TYPES = /\b(bool|int8_t|int16_t|int32_t|uint8_t|uint16_t|uint32_t|float|double|char)\b/g;

  const result: { text: string; className: string }[] = [];
  let remaining = line;

  // Check for inline comments
  const commentIdx = remaining.indexOf('/*');
  const lineCommentIdx = remaining.indexOf('//');
  let commentStart = -1;
  if (commentIdx >= 0 && (lineCommentIdx < 0 || commentIdx < lineCommentIdx)) {
    commentStart = commentIdx;
  } else if (lineCommentIdx >= 0) {
    commentStart = lineCommentIdx;
  }

  let codePart = remaining;
  let commentPart = '';
  if (commentStart >= 0) {
    codePart = remaining.substring(0, commentStart);
    commentPart = remaining.substring(commentStart);
  }

  // Tokenize code part
  let lastIndex = 0;
  const combined = new RegExp(`(${C_KEYWORDS.source})|(${C_TYPES.source})`, 'g');
  let match;
  while ((match = combined.exec(codePart)) !== null) {
    if (match.index > lastIndex) {
      result.push({ text: codePart.substring(lastIndex, match.index), className: '' });
    }
    if (match[1]) {
      result.push({ text: match[0], className: 'text-blue-400 font-semibold' });
    } else {
      result.push({ text: match[0], className: 'text-green-400' });
    }
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < codePart.length) {
    result.push({ text: codePart.substring(lastIndex), className: '' });
  }

  if (commentPart) {
    result.push({ text: commentPart, className: 'text-muted-foreground/60' });
  }

  return result;
}

function HighlightedSCL({ code }: { code: string }) {
  const lines = code.split('\n');
  return (
    <>
      {lines.map((line, i) => (
        <SCLLine key={i} line={line} />
      ))}
    </>
  );
}

function SCLLine({ line }: { line: string }) {
  const parts = tokenizeSCLLine(line);
  return (
    <span>
      {parts.map((part, i) => (
        <span key={i} className={part.className}>{part.text}</span>
      ))}
      {'\n'}
    </span>
  );
}

function tokenizeSCLLine(line: string): { text: string; className: string }[] {
  const result: { text: string; className: string }[] = [];

  // Check for (* comment *)
  const commentMatch = line.match(/(\(\*.*?\*\))/);
  if (commentMatch && commentMatch.index !== undefined) {
    const before = line.substring(0, commentMatch.index);
    const comment = commentMatch[0];
    const after = line.substring(commentMatch.index + comment.length);

    if (before) result.push(...tokenizeSCLCode(before));
    result.push({ text: comment, className: 'text-muted-foreground/60' });
    if (after) result.push(...tokenizeSCLCode(after));
    return result;
  }

  // // comment
  const lineCommentIdx = line.indexOf('//');
  if (lineCommentIdx >= 0) {
    const before = line.substring(0, lineCommentIdx);
    const comment = line.substring(lineCommentIdx);
    if (before) result.push(...tokenizeSCLCode(before));
    result.push({ text: comment, className: 'text-muted-foreground/60' });
    return result;
  }

  return tokenizeSCLCode(line);
}

function tokenizeSCLCode(line: string): { text: string; className: string }[] {
  const SCL_KEYWORDS = /\b(FUNCTION_BLOCK|END_FUNCTION_BLOCK|VAR_INPUT|VAR_OUTPUT|VAR CONSTANT|VAR|END_VAR|BEGIN|CASE|END_CASE|OF|IF|ELSIF|ELSE|END_IF|THEN|AND|OR|NOT|TRUE|FALSE)\b/g;
  const SCL_TYPES = /\b(BOOL|SINT|INT|DINT|USINT|UINT|UDINT|REAL|LREAL|STRING)\b/g;
  const SCL_REFS = /(#\w+)/g;

  const result: { text: string; className: string }[] = [];
  const combined = new RegExp(`(${SCL_KEYWORDS.source})|(${SCL_TYPES.source})|(${SCL_REFS.source})`, 'g');

  let lastIndex = 0;
  let match;
  while ((match = combined.exec(line)) !== null) {
    if (match.index > lastIndex) {
      result.push({ text: line.substring(lastIndex, match.index), className: '' });
    }
    if (match[1]) {
      result.push({ text: match[0], className: 'text-blue-400 font-semibold' });
    } else if (match[2]) {
      result.push({ text: match[0], className: 'text-green-400' });
    } else {
      result.push({ text: match[0], className: 'text-orange-400' });
    }
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < line.length) {
    result.push({ text: line.substring(lastIndex), className: '' });
  }

  return result;
}

