'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import { useProjectStore } from '@/lib/store/project-store';
import { useNavigationStore } from '@/lib/store/navigation-store';
import type { Variable, VariableScope, DataType } from '@/lib/types/variable';
import { Plus, Trash2, ChevronRight, ChevronDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';

const SCOPES: { value: VariableScope; label: string }[] = [
  { value: 'input', label: 'INP' },
  { value: 'output', label: 'OUT' },
  { value: 'local', label: 'LOC' },
  { value: 'parameter', label: 'PAR' },
];

const DATA_TYPES: { value: DataType; label: string }[] = [
  { value: 'boolean', label: 'bool' },
  { value: 'int8', label: 'i8' },
  { value: 'int16', label: 'i16' },
  { value: 'int32', label: 'i32' },
  { value: 'uint8', label: 'u8' },
  { value: 'uint16', label: 'u16' },
  { value: 'uint32', label: 'u32' },
  { value: 'float', label: 'f32' },
  { value: 'double', label: 'f64' },
  { value: 'string', label: 'str' },
  { value: 'enum', label: 'enum' },
];

const SCOPE_COLORS: Record<VariableScope, string> = {
  input: '#22c55e',
  output: '#f97316',
  local: '#3b82f6',
  parameter: '#a855f7',
};

const NAME_REGEX = /^[a-zA-Z_][a-zA-Z0-9_]*$/;

export function VariableTable() {
  const chartId = useNavigationStore((s) =>
    s.activeView.type === 'chart' ? s.activeView.chartId : null
  );
  const variables = useProjectStore((s) => {
    if (!chartId || !s.currentProject) return [];
    const chart = s.currentProject.charts.find((c) => c.id === chartId);
    return chart?.variables ?? [];
  });
  const addVariableStore = useProjectStore((s) => s.addVariable);
  const updateVariableStore = useProjectStore((s) => s.updateVariable);
  const removeVariableStore = useProjectStore((s) => s.removeVariable);

  const addVariable = useCallback(
    (variable: Omit<Variable, 'id'>) => {
      if (!chartId) return '';
      return addVariableStore(chartId, variable);
    },
    [chartId, addVariableStore]
  );
  const updateVariable = useCallback(
    (varId: string, updates: Partial<Variable>) => {
      if (!chartId) return;
      updateVariableStore(chartId, varId, updates);
    },
    [chartId, updateVariableStore]
  );
  const removeVariable = useCallback(
    (varId: string) => {
      if (!chartId) return;
      removeVariableStore(chartId, varId);
    },
    [chartId, removeVariableStore]
  );

  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [newRowId, setNewRowId] = useState<string | null>(null);
  const newNameRef = useRef<HTMLInputElement>(null);

  // Focus name input when a new row is added
  useEffect(() => {
    if (newRowId && newNameRef.current) {
      newNameRef.current.focus();
      newNameRef.current.select();
      setNewRowId(null);
    }
  }, [newRowId, variables]);

  const handleAdd = useCallback(() => {
    const id = addVariable({
      name: 'newVar',
      scope: 'local',
      dataType: 'int32',
      initialValue: '0',
      description: '',
    });
    setNewRowId(id);
  }, [addVariable]);

  const toggleExpanded = useCallback((id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  if (variables.length === 0) {
    return (
      <div className="flex flex-col h-full">
        <div className="flex items-center justify-between px-2 pt-2">
          <span className="text-xs font-medium text-muted-foreground">
            Variables (0)
          </span>
          <Button
            variant="ghost"
            size="icon"
            className="h-6 w-6"
            onClick={handleAdd}
          >
            <Plus className="h-3.5 w-3.5" />
          </Button>
        </div>
        <div className="flex flex-col items-center justify-center py-8 text-center text-sm text-muted-foreground flex-1">
          <p>No variables defined</p>
          <p className="text-xs mt-1">Click + to add a variable</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="flex items-center justify-between px-2 pt-2">
        <span className="text-xs font-medium text-muted-foreground">
          Variables ({variables.length})
        </span>
        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={handleAdd}
        >
          <Plus className="h-3.5 w-3.5" />
        </Button>
      </div>
      <ScrollArea className="flex-1">
        <table className="w-full text-[10px] font-mono border-collapse">
          <thead>
            <tr className="text-muted-foreground">
              <th className="text-left py-1 px-1 font-medium w-[3.2rem]">Scope</th>
              <th className="text-left py-1 px-1 font-medium">Name</th>
              <th className="text-left py-1 px-1 font-medium w-[3.2rem]">Type</th>
              <th className="text-left py-1 px-1 font-medium w-[3.5rem]">Init</th>
              <th className="w-5"></th>
            </tr>
          </thead>
          <tbody>
            {variables.map((v) => (
              <VariableRow
                key={v.id}
                variable={v}
                isExpanded={expandedIds.has(v.id)}
                onToggleExpand={() => toggleExpanded(v.id)}
                onUpdate={(updates) => updateVariable(v.id, updates)}
                onDelete={() => removeVariable(v.id)}
                nameRef={v.id === newRowId ? newNameRef : undefined}
              />
            ))}
          </tbody>
        </table>
      </ScrollArea>
    </div>
  );
}

function VariableRow({
  variable,
  isExpanded,
  onToggleExpand,
  onUpdate,
  onDelete,
  nameRef,
}: {
  variable: Variable;
  isExpanded: boolean;
  onToggleExpand: () => void;
  onUpdate: (updates: Partial<Variable>) => void;
  onDelete: () => void;
  nameRef?: React.RefObject<HTMLInputElement | null>;
}) {
  const [localName, setLocalName] = useState(variable.name);
  const [localInit, setLocalInit] = useState(variable.initialValue);
  const [nameError, setNameError] = useState(false);

  // Sync from store when variable changes externally
  useEffect(() => {
    setLocalName(variable.name);
    setLocalInit(variable.initialValue);
  }, [variable.name, variable.initialValue]);

  const commitName = useCallback(() => {
    const trimmed = localName.trim();
    if (!trimmed || !NAME_REGEX.test(trimmed)) {
      setNameError(true);
      // Revert to store value if empty
      if (!trimmed) {
        setLocalName(variable.name);
        setNameError(false);
      }
      return;
    }
    setNameError(false);
    if (trimmed !== variable.name) {
      onUpdate({ name: trimmed });
    }
  }, [localName, variable.name, onUpdate]);

  const commitInit = useCallback(() => {
    const trimmed = localInit.trim();
    if (trimmed !== variable.initialValue) {
      onUpdate({ initialValue: trimmed });
    }
  }, [localInit, variable.initialValue, onUpdate]);

  const handleKeyDown = (e: React.KeyboardEvent, commit: () => void) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      commit();
      (e.target as HTMLElement).blur();
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      setLocalName(variable.name);
      setLocalInit(variable.initialValue);
      setNameError(false);
      (e.target as HTMLElement).blur();
    }
  };

  const hasDetails = variable.description || variable.dataType === 'enum';

  return (
    <>
      <tr className="group hover:bg-accent/30 border-b border-border/20">
        {/* Scope */}
        <td className="py-0.5 px-1">
          <select
            value={variable.scope}
            onChange={(e) => onUpdate({ scope: e.target.value as VariableScope })}
            className="w-full bg-transparent border-0 outline-none text-[10px] font-mono font-medium cursor-pointer p-0 appearance-auto"
            style={{ color: SCOPE_COLORS[variable.scope] }}
          >
            {SCOPES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </td>

        {/* Name with expand toggle */}
        <td className="py-0.5 px-1">
          <div className="flex items-center gap-0.5">
            <button
              onClick={onToggleExpand}
              className="flex-shrink-0 p-0 text-muted-foreground/50 hover:text-muted-foreground"
              title={hasDetails ? 'Show details' : 'Add description'}
            >
              {isExpanded ? (
                <ChevronDown className="h-2.5 w-2.5" />
              ) : (
                <ChevronRight className="h-2.5 w-2.5" />
              )}
            </button>
            <input
              ref={nameRef}
              type="text"
              value={localName}
              onChange={(e) => {
                setLocalName(e.target.value);
                setNameError(false);
              }}
              onBlur={commitName}
              onKeyDown={(e) => handleKeyDown(e, commitName)}
              className={`w-full bg-transparent outline-none text-[10px] font-mono font-medium px-0.5 rounded ${
                nameError
                  ? 'ring-1 ring-destructive text-destructive'
                  : 'focus:ring-1 focus:ring-ring'
              }`}
              spellCheck={false}
            />
          </div>
        </td>

        {/* Data Type */}
        <td className="py-0.5 px-1">
          <select
            value={variable.dataType}
            onChange={(e) => {
              const newType = e.target.value as DataType;
              onUpdate({ dataType: newType });
              // Auto-expand when enum is selected
              if (newType === 'enum' && !isExpanded) {
                onToggleExpand();
              }
            }}
            className="w-full bg-transparent border-0 outline-none text-[10px] font-mono cursor-pointer p-0 text-muted-foreground appearance-auto"
          >
            {DATA_TYPES.map((dt) => (
              <option key={dt.value} value={dt.value}>
                {dt.label}
              </option>
            ))}
          </select>
        </td>

        {/* Initial Value */}
        <td className="py-0.5 px-1">
          <input
            type="text"
            value={localInit}
            onChange={(e) => setLocalInit(e.target.value)}
            onBlur={commitInit}
            onKeyDown={(e) => handleKeyDown(e, commitInit)}
            className="w-full bg-transparent outline-none text-[10px] font-mono text-muted-foreground px-0.5 rounded focus:ring-1 focus:ring-ring"
            placeholder="—"
            spellCheck={false}
          />
        </td>

        {/* Delete */}
        <td className="py-0.5 px-0.5">
          <button
            onClick={onDelete}
            className="p-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity hover:bg-destructive/10"
          >
            <Trash2 className="h-2.5 w-2.5 text-muted-foreground hover:text-destructive" />
          </button>
        </td>
      </tr>

      {/* Expandable detail row */}
      {isExpanded && (
        <ExpandedDetailRow variable={variable} onUpdate={onUpdate} />
      )}
    </>
  );
}

function ExpandedDetailRow({
  variable,
  onUpdate,
}: {
  variable: Variable;
  onUpdate: (updates: Partial<Variable>) => void;
}) {
  const [localDesc, setLocalDesc] = useState(variable.description);
  const [localEnum, setLocalEnum] = useState(
    variable.enumValues?.join(', ') ?? ''
  );

  useEffect(() => {
    setLocalDesc(variable.description);
    setLocalEnum(variable.enumValues?.join(', ') ?? '');
  }, [variable.description, variable.enumValues]);

  const commitDesc = useCallback(() => {
    const trimmed = localDesc.trim();
    if (trimmed !== variable.description) {
      onUpdate({ description: trimmed });
    }
  }, [localDesc, variable.description, onUpdate]);

  const commitEnum = useCallback(() => {
    const values = localEnum
      .split(',')
      .map((v) => v.trim())
      .filter(Boolean);
    const current = variable.enumValues ?? [];
    if (JSON.stringify(values) !== JSON.stringify(current)) {
      onUpdate({ enumValues: values });
    }
  }, [localEnum, variable.enumValues, onUpdate]);

  const handleKeyDown = (e: React.KeyboardEvent, commit: () => void) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      commit();
      (e.target as HTMLElement).blur();
    }
  };

  return (
    <tr className="bg-muted/30 border-b border-border/20">
      <td colSpan={5} className="px-2 py-1.5">
        <div className="space-y-1.5 pl-3">
          <div className="flex items-center gap-1.5">
            <span className="text-[9px] text-muted-foreground w-8 flex-shrink-0">
              Desc
            </span>
            <input
              type="text"
              value={localDesc}
              onChange={(e) => setLocalDesc(e.target.value)}
              onBlur={commitDesc}
              onKeyDown={(e) => handleKeyDown(e, commitDesc)}
              className="flex-1 bg-transparent outline-none text-[10px] font-mono px-1 py-0.5 rounded focus:ring-1 focus:ring-ring"
              placeholder="Description..."
              spellCheck={false}
            />
          </div>
          {variable.dataType === 'enum' && (
            <div className="flex items-center gap-1.5">
              <span className="text-[9px] text-muted-foreground w-8 flex-shrink-0">
                Vals
              </span>
              <input
                type="text"
                value={localEnum}
                onChange={(e) => setLocalEnum(e.target.value)}
                onBlur={commitEnum}
                onKeyDown={(e) => handleKeyDown(e, commitEnum)}
                className="flex-1 bg-transparent outline-none text-[10px] font-mono px-1 py-0.5 rounded focus:ring-1 focus:ring-ring"
                placeholder="OFF, ON, ERROR"
                spellCheck={false}
              />
            </div>
          )}
        </div>
      </td>
    </tr>
  );
}

import type { CanvasNode, TransitionEdge } from '../types/canvas';
import type { Variable } from '../types/variable';
import type { StateMachineModel, ModelState, ModelTransition } from '../types/codegen';

/**
 * Convert a C-unsafe name to a safe identifier
 */
function toSafeName(name: string): string {
  return name
    .replace(/[^a-zA-Z0-9_]/g, '_')
    .replace(/^(\d)/, '_$1')
    .replace(/_+/g, '_')
    .toUpperCase();
}

/**
 * Build a StateMachineModel from canvas nodes, edges, and variables
 */
export function buildModel(
  nodes: CanvasNode[],
  edges: TransitionEdge[],
  variables: Variable[],
  projectName: string = 'StateMachine'
): StateMachineModel {
  const stateNodes = nodes.filter((n) => n.type === 'stateNode');
  const defaultTransitionNodes = nodes.filter((n) => n.type === 'defaultTransition');

  // Build states
  const states: ModelState[] = stateNodes.map((node) => {
    const block = node.data.stateBlock;
    const childIds = stateNodes
      .filter((n) => n.data.stateBlock.parentId === node.id)
      .map((n) => n.id);

    return {
      id: node.id,
      name: block.name,
      safeName: toSafeName(block.name),
      parentId: block.parentId,
      decomposition: block.decomposition,
      isDefault: block.isDefault,
      childIds,
      actions: {
        entry: block.actions.entry
          .sort((a, b) => a.order - b.order)
          .map((a) => a.code)
          .filter((c) => c.trim()),
        during: block.actions.during
          .sort((a, b) => a.order - b.order)
          .map((a) => a.code)
          .filter((c) => c.trim()),
        exit: block.actions.exit
          .sort((a, b) => a.order - b.order)
          .map((a) => a.code)
          .filter((c) => c.trim()),
      },
    };
  });

  // Build transitions
  const transitions: ModelTransition[] = edges.map((edge) => {
    // For default transitions, the source is a dot node
    const isDefault = edge.data?.isDefault ?? false;
    const sourceNode = nodes.find((n) => n.id === edge.source);
    let sourceId = edge.source;

    if (sourceNode?.type === 'defaultTransition') {
      // The source of a default transition is really the parent context
      sourceId = edge.source; // Keep as-is, validator will handle
    }

    return {
      id: edge.id,
      sourceId,
      targetId: edge.target,
      event: edge.data?.label.event ?? null,
      condition: edge.data?.label.condition ?? null,
      conditionAction: edge.data?.label.conditionAction ?? null,
      transitionAction: edge.data?.label.transitionAction ?? null,
      priority: edge.data?.priority ?? 0,
      isDefault,
    };
  });

  // Sort transitions by priority
  transitions.sort((a, b) => a.priority - b.priority);

  // Find root states (no parent)
  const rootStateIds = states
    .filter((s) => s.parentId === null)
    .map((s) => s.id);

  // Find the default state (via default transition or isDefault flag)
  let defaultStateId: string | null = null;

  // First check for default transitions pointing to root states
  const defaultTransitions = transitions.filter((t) => t.isDefault);
  for (const dt of defaultTransitions) {
    const targetState = states.find((s) => s.id === dt.targetId);
    if (targetState && targetState.parentId === null) {
      defaultStateId = targetState.id;
      break;
    }
  }

  // Fallback: check isDefault flag
  if (!defaultStateId) {
    const defaultState = states.find((s) => s.isDefault && s.parentId === null);
    if (defaultState) {
      defaultStateId = defaultState.id;
    }
  }

  // Fallback: first root state
  if (!defaultStateId && rootStateIds.length > 0) {
    defaultStateId = rootStateIds[0];
  }

  return {
    name: toSafeName(projectName),
    states,
    transitions,
    variables,
    rootStateIds,
    defaultStateId,
  };
}

import type { Project, AnnotationData } from '../types/project';
import type { Chart } from '../types/chart';
import type { StateBlock } from '../types/state';
import type { Transition } from '../types/transition';
import type {
  CanvasNode,
  TransitionEdge,
  StateNode,
  DefaultTransitionNode,
  AnnotationNode,
  ChartBlockNode,
  SourceBlockNode,
  SinkBlockNode,
  SystemWireEdge,
} from '../types/canvas';
import type { SystemBlock, SystemWire } from '../types/system';
import { DEFAULT_STATE_SIZE } from '../types/state';
import { EMPTY_TRANSITION_LABEL } from '../types/transition';
import { DEFAULT_ANNOTATION_SIZE } from '../utils/constants';

// ─── Chart Serialization ────────────────────────────────────────

/**
 * Serialize canvas state (nodes + edges) back into a Chart's data
 */
export function serializeCanvasToChart(
  chart: Chart,
  nodes: CanvasNode[],
  edges: TransitionEdge[],
  viewport?: { x: number; y: number; zoom: number }
): Chart {
  const states: StateBlock[] = [];
  const transitions: Transition[] = [];
  const annotations: AnnotationData[] = [];

  for (const node of nodes) {
    if (node.type === 'stateNode') {
      states.push({
        ...node.data.stateBlock,
        position: node.position,
        size: {
          width: (node.style?.width as number) ?? DEFAULT_STATE_SIZE.width,
          height: (node.style?.height as number) ?? DEFAULT_STATE_SIZE.height,
        },
      });
    } else if (node.type === 'annotationNode') {
      annotations.push({
        id: node.id,
        content: node.data.content,
        position: node.position,
        size: {
          width: (node.style?.width as number) ?? DEFAULT_ANNOTATION_SIZE.width,
          height: (node.style?.height as number) ?? DEFAULT_ANNOTATION_SIZE.height,
        },
        color: node.data.color,
        image: node.data.image,
        fontSize: node.data.fontSize ?? 14,
      });
    }
  }

  for (const edge of edges) {
    transitions.push({
      id: edge.id,
      sourceStateId: edge.source,
      targetStateId: edge.target,
      sourceHandle: edge.sourceHandle ?? '',
      targetHandle: edge.targetHandle ?? '',
      label: edge.data?.label ?? { ...EMPTY_TRANSITION_LABEL },
      priority: edge.data?.priority ?? 0,
      isDefault: edge.data?.isDefault ?? false,
    });
  }

  return {
    ...chart,
    states,
    transitions,
    annotations,
    ...(viewport ? { viewport } : {}),
  };
}

/**
 * Deserialize a Chart into canvas nodes and edges
 */
export function deserializeChartToCanvas(chart: Chart): {
  nodes: CanvasNode[];
  edges: TransitionEdge[];
} {
  const nodes: CanvasNode[] = [];
  const edges: TransitionEdge[] = [];

  for (const state of chart.states) {
    const stateNode: StateNode = {
      id: state.id,
      type: 'stateNode',
      position: state.position,
      ...(state.parentId
        ? { parentId: state.parentId, extent: 'parent' as const }
        : {}),
      data: {
        stateBlock: state,
        isHighlighted: false,
        isDropTarget: false,
        validationErrors: [],
      },
      style: {
        width: state.size.width,
        height: state.size.height,
      },
    };
    nodes.push(stateNode);
  }

  for (const transition of chart.transitions) {
    if (transition.isDefault) {
      const sourceExists = chart.states.some(
        (s) => s.id === transition.sourceStateId
      );
      if (!sourceExists) {
        const targetState = chart.states.find(
          (s) => s.id === transition.targetStateId
        );
        if (targetState) {
          const nodeWidth = targetState.size.width;
          const dotNode: DefaultTransitionNode = {
            id: transition.sourceStateId,
            type: 'defaultTransition',
            position: {
              x: targetState.position.x + nodeWidth / 2 - 8,
              y: targetState.position.y - 40,
            },
            ...(targetState.parentId
              ? { parentId: targetState.parentId, extent: 'parent' as const }
              : {}),
            data: { targetStateId: transition.targetStateId },
            style: { width: 16, height: 16 },
          };
          nodes.push(dotNode);
        }
      }
    }

    const edge: TransitionEdge = {
      id: transition.id,
      source: transition.sourceStateId,
      target: transition.targetStateId,
      sourceHandle: transition.sourceHandle || (transition.isDefault ? 'default-source' : undefined),
      targetHandle: transition.targetHandle || (transition.isDefault ? 'top-3' : undefined),
      type: 'transition',
      data: {
        transitionId: transition.id,
        label: transition.label,
        priority: transition.priority,
        isDefault: transition.isDefault,
        labelOffsetX: 0,
        labelOffsetY: 0,
      },
    };
    edges.push(edge);
  }

  if (chart.annotations) {
    for (const anno of chart.annotations) {
      const annotationNode: AnnotationNode = {
        id: anno.id,
        type: 'annotationNode',
        position: anno.position,
        data: {
          content: anno.content,
          color: anno.color,
          image: anno.image,
          fontSize: anno.fontSize ?? 14,
        },
        style: {
          width: anno.size.width,
          height: anno.size.height,
        },
      };
      nodes.push(annotationNode);
    }
  }

  return { nodes, edges };
}

// ─── System Serialization ───────────────────────────────────────

/**
 * Serialize the system canvas back into system blocks + wires
 * Updates positions/sizes from the canvas nodes, wires from edges
 */
export function serializeSystemCanvas(
  currentBlocks: SystemBlock[],
  currentWires: SystemWire[],
  nodes: CanvasNode[],
  edges: TransitionEdge[]
): { blocks: SystemBlock[]; wires: SystemWire[] } {
  const blocks = currentBlocks.map((block) => {
    const node = nodes.find((n) => n.id === block.id);
    if (!node) return block;
    return {
      ...block,
      position: node.position,
      size: {
        width: (node.style?.width as number) ?? block.size.width,
        height: (node.style?.height as number) ?? block.size.height,
      },
    };
  });

  // Serialize wire edges back to SystemWire data
  const wires: SystemWire[] = [];
  for (const edge of edges) {
    if (edge.type === 'systemWire' && edge.data) {
      const wireData = edge.data as unknown as { wireId: string };
      wires.push({
        id: wireData.wireId ?? edge.id,
        sourceBlockId: edge.source,
        sourcePortId: edge.sourceHandle ?? '',
        targetBlockId: edge.target,
        targetPortId: edge.targetHandle ?? '',
      });
    }
  }

  return { blocks, wires };
}

/**
 * Deserialize system blocks + wires into canvas nodes and edges
 */
export function deserializeSystemToCanvas(project: Project): {
  nodes: CanvasNode[];
  edges: TransitionEdge[];
} {
  const nodes: CanvasNode[] = [];
  const edges: TransitionEdge[] = [];

  for (const block of project.systemBlocks) {
    if (block.type === 'chart') {
      const chart = project.charts.find((c) => c.id === block.chartId);
      const chartNode: ChartBlockNode = {
        id: block.id,
        type: 'chartBlock',
        position: block.position,
        data: {
          chartId: block.chartId ?? '',
          chartName: chart?.name ?? block.name,
          ports: chart?.ports ?? [],
        },
        style: {
          width: block.size.width,
          height: block.size.height,
        },
      };
      nodes.push(chartNode);
    } else if (block.type === 'constant' || block.type === 'signalGenerator') {
      const sourceNode: SourceBlockNode = {
        id: block.id,
        type: 'sourceBlock',
        position: block.position,
        data: {
          blockType: block.type,
          name: block.name,
          config: { ...block.config },
        },
        style: {
          width: block.size.width,
          height: block.size.height,
        },
      };
      nodes.push(sourceNode);
    } else if (block.type === 'scope' || block.type === 'display') {
      const sinkNode: SinkBlockNode = {
        id: block.id,
        type: 'sinkBlock',
        position: block.position,
        data: {
          blockType: block.type,
          name: block.name,
          config: { ...block.config },
        },
        style: {
          width: block.size.width,
          height: block.size.height,
        },
      };
      nodes.push(sinkNode);
    }
  }

  // Deserialize system wires as edges
  for (const wire of project.systemWires) {
    const wireEdge: SystemWireEdge = {
      id: `wire-${wire.id}`,
      source: wire.sourceBlockId,
      target: wire.targetBlockId,
      sourceHandle: wire.sourcePortId || undefined,
      targetHandle: wire.targetPortId || undefined,
      type: 'systemWire',
      data: {
        wireId: wire.id,
      },
    };
    // Cast to TransitionEdge for canvas store compatibility
    edges.push(wireEdge as unknown as TransitionEdge);
  }

  return { nodes, edges };
}

// ─── Legacy Compat (wraps new functions) ────────────────────────

/**
 * @deprecated Use serializeCanvasToChart + serializeSystemCanvas instead.
 * Kept for backward compatibility during transition.
 */
export function serializeCanvasToProject(
  project: Project,
  nodes: CanvasNode[],
  edges: TransitionEdge[]
): Project {
  // This should not be called in the new architecture,
  // but if it is, we return the project as-is with updated timestamp
  return {
    ...project,
    updatedAt: new Date().toISOString(),
  };
}

import type { ASTNode } from './types';
import { parse, parseExpression } from './parser';
import { emitC, emitCStatement, emitCCondition, type CEmitOptions } from './c-emitter';
import { emitSCL, emitSCLStatement, emitSCLCondition, type SCLEmitOptions } from './scl-emitter';

/**
 * Translate a condition string to C.
 * Falls back to raw string if parsing fails.
 */
export function translateConditionToC(
  input: string,
  opts: CEmitOptions = {}
): string {
  if (!input.trim()) return '';
  const { node } = parseExpression(input);
  if (!node) return input; // fallback
  return emitCCondition(node, opts);
}

/**
 * Translate an action string (may contain multiple statements) to C.
 * Returns array of C statements.
 */
export function translateActionToC(
  input: string,
  opts: CEmitOptions = {}
): string[] {
  if (!input.trim()) return [];
  const { statements, errors } = parse(input);
  if (errors.length > 0 || statements.length === 0) return [input + ';']; // fallback
  return statements.map((s) => emitCStatement(s, opts));
}

/**
 * Translate a condition string to SCL.
 * Falls back to raw string if parsing fails.
 */
export function translateConditionToSCL(
  input: string,
  opts: SCLEmitOptions = {}
): string {
  if (!input.trim()) return '';
  const { node } = parseExpression(input);
  if (!node) return input; // fallback
  return emitSCLCondition(node, opts);
}

/**
 * Translate an action string (may contain multiple statements) to SCL.
 * Returns array of SCL statements.
 */
export function translateActionToSCL(
  input: string,
  opts: SCLEmitOptions = {}
): string[] {
  if (!input.trim()) return [];
  const { statements, errors } = parse(input);
  if (errors.length > 0 || statements.length === 0) return [input + ';']; // fallback
  return statements.map((s) => emitSCLStatement(s, opts));
}

/**
 * Check if any expression in a list uses temporal operators.
 * Used by generators to decide whether to add tick counter variables.
 */
export function usesTemporalLogic(expressions: string[]): boolean {
  for (const input of expressions) {
    if (!input.trim()) continue;
    const { statements } = parse(input);
    for (const stmt of statements) {
      if (hasTemporalNode(stmt)) return true;
    }
    // Also try as expression
    const { node } = parseExpression(input);
    if (node && hasTemporalNode(node)) return true;
  }
  return false;
}

function hasTemporalNode(node: ASTNode): boolean {
  switch (node.type) {
    case 'temporal':
    case 'elapsed':
      return true;
    case 'binary':
      return hasTemporalNode(node.left) || hasTemporalNode(node.right);
    case 'unary':
      return hasTemporalNode(node.operand);
    case 'call':
      return node.args.some(hasTemporalNode);
    case 'assignment':
      return hasTemporalNode(node.value);
    default:
      return false;
  }
}
